"""Loopback HTTP surface for the account recovery service.

Only three routes exist: POST /recovery/start and POST /recovery/complete
are reachable by a user who has already lost access (no bearer token
required), while POST /recovery/notifications/retry is an administrative
action and always requires the configured bearer token.
"""
from __future__ import annotations

import hmac
import json
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Optional

from . import recovery
from .recovery import RecoveryService
from .storage import ConflictError, NotFoundError, ValidationError

MAX_BODY_BYTES = 16_384


class AccountRecoveryServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, address, handler_cls, *, recovery_service: RecoveryService, bearer_token: str) -> None:
        super().__init__(address, handler_cls)
        self.recovery_service = recovery_service
        self.bearer_token = bearer_token


class RecoveryRequestHandler(BaseHTTPRequestHandler):
    server: AccountRecoveryServer

    def log_message(self, format, *args):  # noqa: A002 - stdlib signature
        pass  # Keep loopback test/service runs quiet; errors still raise.

    def do_POST(self) -> None:  # noqa: N802 - stdlib method name
        if self.path == "/recovery/start":
            self._handle_start()
        elif self.path == "/recovery/complete":
            self._handle_complete()
        elif self.path == "/recovery/notifications/retry":
            self._handle_retry()
        else:
            self._send_json(HTTPStatus.NOT_FOUND, {"error": "not_found"})

    def _read_body(self) -> Optional[dict]:
        length_header = self.headers.get("Content-Length")
        if length_header is None:
