"""Test doubles shared across the accountsvc test suite."""
from __future__ import annotations

import json
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import List, Optional, Tuple

from accountsvc.mailer import DeliveryOutcome
from accountsvc import models


class FakeMailer:
    """Duck-typed stand-in for accountsvc.mailer.Mailer.

    `responses` is consumed one entry per send() call; the last entry is
    reused once the queue is exhausted, so a test can queue "fail then
    succeed" sequences to exercise retry.
    """

    def __init__(self, responses: List[DeliveryOutcome]) -> None:
        self._responses = list(responses)
        self.calls: List[Tuple[str, str, str]] = []

    def send(self, *, recipient: str, recovery_token: str, reconciliation_id: str) -> DeliveryOutcome:
        self.calls.append((recipient, recovery_token, reconciliation_id))
        if len(self._responses) > 1:
            return self._responses.pop(0)
        return self._responses[0]


def delivered(receipt: Optional[str] = "receipt-ok") -> DeliveryOutcome:
    return DeliveryOutcome(delivery_state=models.DeliveryState.DELIVERED, provider_receipt=receipt)


def accepted_delayed(receipt: Optional[str] = "receipt-delayed") -> DeliveryOutcome:
    return DeliveryOutcome(delivery_state=models.DeliveryState.ACCEPTED_DELAYED, provider_receipt=receipt)


def failed(receipt: Optional[str] = "provider unavailable") -> DeliveryOutcome:
    return DeliveryOutcome(delivery_state=models.DeliveryState.FAILED, provider_receipt=receipt)


class _Behavior:
    def __init__(self) -> None:
        self.status = 200
        self.body = b"{}"
        self.captured: List[dict] = []


class FakeMailProviderServer:
    """A tiny real HTTP loopback mail endpoint, controllable per-test."""

    def __init__(self) -> None:
        self.behavior = _Behavior()
        behavior = self.behavior

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, format, *args):
                pass

            def do_POST(self) -> None:  # noqa: N802
                length = int(self.headers.get("Content-Length", "0"))
                raw = self.rfile.read(length)
                try:
                    behavior.captured.append(json.loads(raw.decode("utf-8")))
                except json.JSONDecodeError:
                    behavior.captured.append({})
                body = behavior.body
                self.send_response(behavior.status)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

        self._server = HTTPServer(("127.0.0.1", 0), Handler)
        self._thread = threading.Thread(target=self._server.serve_forever, daemon=True)
        self._thread.start()

    @property
    def url(self) -> str:
        host, port = self._server.server_address
        return f"http://{host}:{port}/mail"

    def set_success(self, *, state: Optional[str] = None, receipt: Optional[str] = None) -> None:
        payload = {}
        if state is not None:
            payload["state"] = state
        if receipt is not None:
            payload["receipt"] = receipt
        self.behavior.status = 200
        self.behavior.body = json.dumps(payload).encode("utf-8")

    def set_failure(self, *, status: int = 503, message: str = "unavailable") -> None:
        self.behavior.status = status
        self.behavior.body = json.dumps({"error": message}).encode("utf-8")

    def last_captured(self) -> Optional[dict]:
        return self.behavior.captured[-1] if self.behavior.captured else None

    def shutdown(self) -> None:
        self._server.shutdown()
        self._server.server_close()
        self._thread.join(timeout=5)

"""Loopback mail delivery client.

Posts a recovery link to the configured mail endpoint and classifies the
response into a delivery state plus an opaque provider receipt. The
receipt's internal shape is never interpreted here or anywhere else in
the service -- it is stored verbatim so a later retry or reconciliation
pass can present it back to whatever provider issued it.
"""
from __future__ import annotations

import json
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Optional

from . import models

MAX_RESPONSE_BYTES = 8192
DEFAULT_TIMEOUT_SECONDS = 5.0


@dataclass(frozen=True)
class DeliveryOutcome:
    delivery_state: str
    provider_receipt: Optional[str]


class Mailer:
    def __init__(self, endpoint: str, *, timeout: float = DEFAULT_TIMEOUT_SECONDS) -> None:
        self._endpoint = endpoint
        self._timeout = timeout

    def send(self, *, recipient: str, recovery_token: str, reconciliation_id: str) -> DeliveryOutcome:
        payload = json.dumps(
            {"recipient": recipient, "recovery_token": recovery_token, "reconciliation_id": reconciliation_id}
        ).encode("utf-8")
        request = urllib.request.Request(
            self._endpoint,
            data=payload,
            method="POST",
            headers={"Content-Type": "application/json"},
        )
        try:
            with urllib.request.urlopen(request, timeout=self._timeout) as response:
                body = response.read(MAX_RESPONSE_BYTES)
                return _classify_success(body)
        except urllib.error.HTTPError as exc:
            with exc:
                body = exc.read(MAX_RESPONSE_BYTES) if exc.fp is not None else b""
            return _classify_failure(body or str(exc).encode("utf-8", "replace"))
        except (urllib.error.URLError, OSError, TimeoutError) as exc:
            return _classify_failure(str(exc).encode("utf-8", "replace"))


def _classify_success(body: bytes) -> DeliveryOutcome:
    text = body.decode("utf-8", "replace")[:MAX_RESPONSE_BYTES]
    state = models.DeliveryState.DELIVERED
    receipt: Optional[str] = text or None
    try:
        parsed = json.loads(text) if text else {}
    except json.JSONDecodeError:
        parsed = {}
    if isinstance(parsed, dict):
        provider_state = parsed.get("state")
        if provider_state == models.DeliveryState.ACCEPTED_DELAYED:
            state = models.DeliveryState.ACCEPTED_DELAYED
        if isinstance(parsed.get("receipt"), str):
            receipt = parsed["receipt"]
    return DeliveryOutcome(delivery_state=state, provider_receipt=receipt)


def _classify_failure(body: bytes) -> DeliveryOutcome:
    text = body.decode("utf-8", "replace")[:MAX_RESPONSE_BYTES]
    return DeliveryOutcome(delivery_state=models.DeliveryState.FAILED, provider_receipt=text or None)

"""Secret recovery token generation and verification.

A recovery token is secret, single-use, and time-limited. Only its salted
hash is ever persisted; the raw token is returned to the caller exactly
once, at creation time, and handed to the mail provider for delivery.
"""
from __future__ import annotations

import hashlib
import hmac
import secrets

TOKEN_BYTES = 32


def generate_token() -> str:
    """Return a new URL-safe random secret token."""

    return secrets.token_urlsafe(TOKEN_BYTES)


def hash_token(token: str) -> str:
    """Return a deterministic, non-reversible digest of a recovery token."""

    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def tokens_match(token: str, token_hash: str) -> bool:
    """Constant-time check that `token` hashes to `token_hash`."""

    return hmac.compare_digest(hash_token(token), token_hash)


def new_request_id() -> str:
    return secrets.token_hex(16)


def new_notification_id() -> str:
    return secrets.token_hex(16)


def new_reconciliation_id() -> str:
    """Return a locally-minted correlation id for a delivery attempt.

    Sent alongside the recipient/token in the outgoing mail request so a
    later reconciliation feed can reference this specific attempt, even
    though the mail provider's own receipt is treated as fully opaque.
    """

    return secrets.token_hex(16)

