"""Loopback HTTP surface for the account recovery service.

POST /recovery/start and POST /recovery/complete are reachable by a user
who has already lost access (no bearer token required). POST
/recovery/notifications/retry and POST /reconciliation/import are
administrative actions and always require the configured bearer token.
"""
from __future__ import annotations

import dataclasses
import hmac
import json
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Optional

from . import recovery
from .reconciliation import ReconciliationEngine
from .recovery import RecoveryService
from .storage import ConflictError, NotFoundError, ValidationError

MAX_BODY_BYTES = 16_384


class AccountRecoveryServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(
        self,
        address,
        handler_cls,
        *,
        recovery_service: RecoveryService,
        bearer_token: str,
        reconciliation_engine: Optional[ReconciliationEngine] = None,
    ) -> None:
        super().__init__(address, handler_cls)
        self.recovery_service = recovery_service
        self.bearer_token = bearer_token
        self.reconciliation_engine = reconciliation_engine


class RecoveryRequestHandler(BaseHTTPRequestHandler):
    server: AccountRecoveryServer

    def log_message(self, format, *args):  # noqa: A002 - stdlib signature
        pass  # Keep loopback test/service runs quiet; errors still raise.

    def do_POST(self) -> None:  # noqa: N802 - stdlib method name
        if self.path == "/recovery/start":
            self._handle_start()
        elif self.path == "/recovery/complete":
            self._handle_complete()
        elif self.path == "/recovery/notifications/retry":
            self._handle_retry()
        elif self.path == "/reconciliation/import":
            self._handle_reconciliation_import()
        else:
            self._send_json(HTTPStatus.NOT_FOUND, {"error": "not_found"})

    def _read_body(self) -> Optional[dict]:
        length_header = self.headers.get("Content-Length")
        if length_header is None:
            self._send_json(HTTPStatus.LENGTH_REQUIRED, {"error": "content_length_required"})
            return None
        try:
            length = int(length_header)
        except ValueError:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "invalid_content_length"})
            return None
        if length < 0 or length > MAX_BODY_BYTES:
            self._send_json(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {"error": "body_too_large"})
            return None
        raw = self.rfile.read(length)
        try:
            parsed = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "invalid_json"})
            return None
        if not isinstance(parsed, dict):
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "invalid_body"})
            return None
        return parsed

    def _is_authenticated(self) -> bool:
        header = self.headers.get("Authorization", "")
        prefix = "Bearer "
        if not header.startswith(prefix):
            return False
        supplied = header[len(prefix):]
        return hmac.compare_digest(supplied, self.server.bearer_token)

    def _handle_start(self) -> None:
        body = self._read_body()
        if body is None:
            return
        try:
            organization = body["organization"]
            email = body["email"]
        except KeyError:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "organization_and_email_required"})
            return
        try:
            result = self.server.recovery_service.start_recovery(organization_id=organization, email=email)
        except ValidationError as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            return
        self._send_json(
            HTTPStatus.ACCEPTED,
            {"request_id": result.request_id, "delivery_status": result.delivery_status},
        )

    def _handle_complete(self) -> None:
        body = self._read_body()
        if body is None:
            return
        try:
            token = body["token"]
        except KeyError:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "token_required"})
            return
        try:
            result = self.server.recovery_service.complete_recovery(token=token)
        except (recovery.TokenInvalidError, recovery.TokenExpiredError, recovery.TokenAlreadyUsedError) as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            return
        except ValidationError as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            return
        self._send_json(
            HTTPStatus.OK,
            {"status": "completed", "account_id": result.account_id, "organization_id": result.organization_id},
        )

    def _handle_retry(self) -> None:
        if not self._is_authenticated():
            self._send_json(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized"})
            return
        body = self._read_body()
        if body is None:
            return
        notification_id = body.get("notification_id")
        try:
            if notification_id is not None:
                updated = [self.server.recovery_service.retry_notification(notification_id)]
            else:
                updated = self.server.recovery_service.retry_pending_notifications()
        except NotFoundError as exc:
            self._send_json(HTTPStatus.NOT_FOUND, {"error": str(exc)})
            return
        except ConflictError as exc:
            self._send_json(HTTPStatus.CONFLICT, {"error": str(exc)})
            return
        self._send_json(
            HTTPStatus.OK,
            {
                "notifications": [
                    {"notification_id": n.notification_id, "delivery_state": n.delivery_state}
                    for n in updated
                ]
            },
        )

    def _handle_reconciliation_import(self) -> None:
        if not self._is_authenticated():
            self._send_json(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized"})
            return
        if self.server.reconciliation_engine is None:
            self._send_json(HTTPStatus.SERVICE_UNAVAILABLE, {"error": "reconciliation_not_configured"})
            return
        body = self._read_body()
        if body is None:
            return
        observations = body.get("observations")
        if not isinstance(observations, list):
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "observations_must_be_a_list"})
            return
        try:
            results = self.server.reconciliation_engine.ingest_feed(observations, now=body.get("now"))
        except (KeyError, TypeError, ValueError, ValidationError) as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": f"malformed_observation: {exc}"})
            return
        except NotFoundError as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            return
        self._send_json(HTTPStatus.OK, {"results": [dataclasses.asdict(r) for r in results]})

    def _send_json(self, status: HTTPStatus, payload: dict) -> None:
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)


def make_server(
    *,
    host: str,
    port: int,
    recovery_service: RecoveryService,
    bearer_token: str,
    reconciliation_engine: Optional[ReconciliationEngine] = None,
) -> AccountRecoveryServer:
    return AccountRecoveryServer(
        (host, port),
        RecoveryRequestHandler,
        recovery_service=recovery_service,
        bearer_token=bearer_token,
        reconciliation_engine=reconciliation_engine,
    )

"""Stdlib-only loaders for the riverbend delayed-delivery fixtures.

accounts-riverbend.yaml uses a narrow, predictable subset of YAML (flat
scalar keys plus one list-of-mappings key), so it is parsed here with a
small indentation-aware reader instead of pulling in a YAML dependency.
"""
from __future__ import annotations

import csv
import json
from typing import Any, Dict, List

MAX_FIXTURE_BYTES = 1_048_576
MAX_LINE_BYTES = 65_536


def _read_bounded(path: str) -> str:
    with open(path, "r", encoding="utf-8") as handle:
        text = handle.read(MAX_FIXTURE_BYTES + 1)
    if len(text) > MAX_FIXTURE_BYTES:
        raise ValueError(f"fixture {path!r} exceeds maximum size of {MAX_FIXTURE_BYTES} bytes")
    return text


def _parse_scalar(value: str) -> Any:
    if value == "":
        return None
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        return value[1:-1]
    lowered = value.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    if lowered in ("null", "~"):
        return None
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value


def load_riverbend_accounts(path: str) -> Dict[str, Any]:
    """Parse the narrow YAML subset used by accounts-riverbend.yaml."""

    root: Dict[str, Any] = {}
    current_list_key = None
    current_item: Dict[str, Any] = None

    for raw_line in _read_bounded(path).splitlines():
        if len(raw_line) > MAX_LINE_BYTES:
            raise ValueError("fixture line exceeds maximum length")
        line = raw_line.rstrip()
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        indent = len(line) - len(line.lstrip(" "))

        if indent == 0:
            current_list_key = None
            current_item = None
            key, _, value = stripped.partition(":")
            key = key.strip()
            value = value.strip()
            if value:
                root[key] = _parse_scalar(value)
            else:
                root[key] = []
                current_list_key = key
            continue

        if stripped.startswith("- "):
            item: Dict[str, Any] = {}
            root[current_list_key].append(item)
            current_item = item
            key, _, value = stripped[2:].partition(":")
            current_item[key.strip()] = _parse_scalar(value.strip())
            continue

        if current_item is not None:
            key, _, value = stripped.partition(":")
            current_item[key.strip()] = _parse_scalar(value.strip())

    return root


def load_delivery_windows(path: str) -> List[Dict[str, Any]]:
    text = _read_bounded(path)
    reader = csv.DictReader(text.splitlines())
    return [dict(row) for row in reader]


def load_reconciliation_feed(path: str) -> List[Dict[str, Any]]:
    records = []
    for line in _read_bounded(path).splitlines():
        line = line.strip()
        if not line:
            continue
        if len(line) > MAX_LINE_BYTES:
            raise ValueError("feed line exceeds maximum length")
        records.append(json.loads(line))
    return records

