input.command:
cd "maintenance/inputs/provider-s02/cursor-history" && POSIX_SCRATCH="/c/Users/Billy/AppData/Local/Temp/claude/C--Users-Billy-AppData-Local-Temp-lcm-live-ixecflwl-provider-s02-delayed-reconciliation/3eba7e9d-25c3-4f69-b02b-078b53a82035/scratchpad" && \
tr -d '\r' < "$POSIX_SCRATCH/norm-jsonl.txt" > "$POSIX_SCRATCH/norm-jsonl-lf.txt" && \
awk -F',' 'NR>1{c=$1;s=$2;st=$3; gsub(/"/,"",c); gsub(/"/,"",s); gsub(/"/,"",st); print c","s","st}' provider-s02-t10-evidence-03.csv | tr -d '\r' > "$POSIX_SCRATCH/norm-csv.txt" && \
awk '
/^- case:/{c=$3}
/^  system:/{s=$2}
/^  status:/{st=$2; print c","s","st}
' provider-s02-t10-evidence-04.yaml | tr -d '\r' > "$POSIX_SCRATCH/norm-yaml.txt" && \
wc -l "$POSIX_SCRATCH/norm-md.txt" "$POSIX_SCRATCH/norm-jsonl-lf.txt" "$POSIX_SCRATCH/norm-csv.txt" "$POSIX_SCRATCH/norm-yaml.txt"

POSIX_SCRATCH="/c/Users/Billy/AppData/Local/Temp/claude/C--Users-Billy-AppData-Local-Temp-lcm-live-ixecflwl-provider-s02-delayed-reconciliation/3eba7e9d-25c3-4f69-b02b-078b53a82035/scratchpad"
cd "$POSIX_SCRATCH"
awk -F',' '
{
  n=NR;
  m=(n-1)%4;
  key=m","$2","$3;
  if(!(key in seen)){seen[key]=1; count[m]++}
  total[m]++;
}
END{
  for(m=0;m<4;m++){
    print "position " m " mod 4: distinct (system,status) combos = " count[m] ", total rows = " total[m]
  }
}' norm-csv.txt
echo "---distinct combos per position---"
awk -F',' '{n=NR; m=(n-1)%4; print m","$2","$3}' norm-csv.txt | sort -u

