"""Loopback HTTP surface for the account recovery service.

POST /recovery/start and POST /recovery/complete are reachable by a user
who has already lost access (no bearer token required). POST
/recovery/notifications/retry, POST /reconciliation/import, and POST
/reconciliation/status are administrative actions and always require the
configured bearer token.
"""
from __future__ import annotations

import dataclasses
import hmac
import json
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Optional

from . import recovery
from .reconciliation import ReconciliationEngine
from .recovery import RecoveryService
from .storage import ConflictError, NotFoundError, ValidationError

MAX_BODY_BYTES = 16_384


class AccountRecoveryServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(
        self,
        address,
        handler_cls,
        *,
        recovery_service: RecoveryService,
        bearer_token: str,
        reconciliation_engine: Optional[ReconciliationEngine] = None,
    ) -> None:
        super().__init__(address, handler_cls)
        self.recovery_service = recovery_service
        self.bearer_token = bearer_token
        self.reconciliation_engine = reconciliation_engine


class RecoveryRequestHandler(BaseHTTPRequestHandler):
    server: AccountRecoveryServer

    def log_message(self, format, *args):  # noqa: A002 - stdlib signature
        pass  # Keep loopback test/service runs quiet; errors still raise.

    def do_POST(self) -> None:  # noqa: N802 - stdlib method name
        if self.path == "/recovery/start":
            self._handle_start()
        elif self.path == "/recovery/complete":
            self._handle_complete()
        elif self.path == "/recovery/notifications/retry":
            self._handle_retry()
        elif self.path == "/reconciliation/import":
            self._handle_reconciliation_import()
        elif self.path == "/reconciliation/status":
            self._handle_reconciliation_status()
        else:
            self._send_json(HTTPStatus.NOT_FOUND, {"error": "not_found"})

    def _read_body(self) -> Optional[dict]:
        length_header = self.headers.get("Content-Length")
        if length_header is None:
            self._send_json(HTTPStatus.LENGTH_REQUIRED, {"error": "content_length_required"})
            return None
        try:
            length = int(length_header)
        except ValueError:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "invalid_content_length"})
            return None
        if length < 0 or length > MAX_BODY_BYTES:
            self._send_json(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {"error": "body_too_large"})
            return None
        raw = self.rfile.read(length)
        try:
            parsed = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "invalid_json"})
            return None
        if not isinstance(parsed, dict):
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "invalid_body"})
            return None
        return parsed

    def _is_authenticated(self) -> bool:
        header = self.headers.get("Authorization", "")
        prefix = "Bearer "
        if not header.startswith(prefix):
            return False
        supplied = header[len(prefix):]
        return hmac.compare_digest(supplied, self.server.bearer_token)

    def _handle_start(self) -> None:
        body = self._read_body()
        if body is None:
            return
        try:
            organization = body["organization"]
            email = body["email"]
        except KeyError:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "organization_and_email_required"})
            return
        try:
            result = self.server.recovery_service.start_recovery(organization_id=organization, email=email)
        except ValidationError as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            return
        self._send_json(
            HTTPStatus.ACCEPTED,
            {"request_id": result.request_id, "delivery_status": result.delivery_status},
        )

    def _handle_complete(self) -> None:
        body = self._read_body()
        if body is None:
            return
        try:
            token = body["token"]
        except KeyError:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "token_required"})
            return
        try:
            result = self.server.recovery_service.complete_recovery(token=token)
        except (recovery.TokenInvalidError, recovery.TokenExpiredError, recovery.TokenAlreadyUsedError) as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            return
        except ValidationError as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            return
        self._send_json(
            HTTPStatus.OK,
            {"status": "completed", "account_id": result.account_id, "organization_id": result.organization_id},
        )

    def _handle_retry(self) -> None:
        if not self._is_authenticated():
            self._send_json(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized"})
            return
        body = self._read_body()
        if body is None:
            return
        notification_id = body.get("notification_id")
        try:
            if notification_id is not None:
                updated = [self.server.recovery_service.retry_notification(notification_id)]
            else:
                updated = self.server.recovery_service.retry_pending_notifications()
        except NotFoundError as exc:
            self._send_json(HTTPStatus.NOT_FOUND, {"error": str(exc)})
            return
        except ConflictError as exc:
            self._send_json(HTTPStatus.CONFLICT, {"error": str(exc)})
            return
        self._send_json(
            HTTPStatus.OK,
            {
                "notifications": [
                    {"notification_id": n.notification_id, "delivery_state": n.delivery_state}
                    for n in updated
                ]
            },
        )

    def _handle_reconciliation_import(self) -> None:
        if not self._is_authenticated():
            self._send_json(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized"})
            return
        if self.server.reconciliation_engine is None:
            self._send_json(HTTPStatus.SERVICE_UNAVAILABLE, {"error": "reconciliation_not_configured"})
            return
        body = self._read_body()
        if body is None:
            return
        observations = body.get("observations")
        if not isinstance(observations, list):
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "observations_must_be_a_list"})
            return
        feed_id = body.get("feed_id")
        page_number = body.get("page_number")
        if (feed_id is None) != (page_number is None):
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": "feed_id_and_page_number_required_together"})
            return
        try:
            if feed_id is None:
                results = self.server.reconciliation_engine.ingest_feed(observations, now=body.get("now"))
                payload = {"results": [dataclasses.asdict(r) for r in results]}
            else:
                page_result = self.server.reconciliation_engine.ingest_page(
                    feed_id=feed_id, page_number=page_number, observations=observations, now=body.get("now")
                )
                payload = {
                    "feed_id": page_result.feed_id,
                    "page_number": page_result.page_number,
                    "committed_page": page_result.committed_page,
                    "skipped": page_result.skipped,
                    "results": [dataclasses.asdict(r) for r in page_result.results],
                }
        except (KeyError, TypeError, ValueError, ValidationError) as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": f"malformed_observation: {exc}"})
            return
        except NotFoundError as exc:
            self._send_json(HTTPStatus.BAD_REQUEST, {"error": str(exc)})
            return
        self._send_json(HTTPStatus.OK, payload)

    def _handle_reconciliation_status(self) -> None:
        if not self._is_authenticated():
            self._send_json(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized"})
            return
        if self.server.reconciliation_engine is None:
            self._send_json(HTTPStatus.SERVICE_UNAVAILABLE, {"error": "reconciliation_not_configured"})
            return
        body = self._read_body()
        if body is None:
            return
        classifications = self.server.reconciliation_engine.classify_delayed_attempts(now=body.get("now"))
        self._send_json(HTTPStatus.OK, {"attempts": [dataclasses.asdict(c) for c in classifications]})

    def _send_json(self, status: HTTPStatus, payload: dict) -> None:
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)


def make_server(
    *,
    host: str,
    port: int,
    recovery_service: RecoveryService,
    bearer_token: str,
    reconciliation_engine: Optional[ReconciliationEngine] = None,
) -> AccountRecoveryServer:
    return AccountRecoveryServer(
        (host, port),
        RecoveryRequestHandler,
        recovery_service=recovery_service,
        bearer_token=bearer_token,
        reconciliation_engine=reconciliation_engine,
    )

"""Test doubles shared across the accountsvc test suite."""
from __future__ import annotations

import json
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import List, Optional, Tuple

from accountsvc.mailer import DeliveryOutcome
from accountsvc import models


class FakeMailer:
    """Duck-typed stand-in for accountsvc.mailer.Mailer.

    `responses` is consumed one entry per send() call; the last entry is
    reused once the queue is exhausted, so a test can queue "fail then
    succeed" sequences to exercise retry.
    """

    def __init__(self, responses: List[DeliveryOutcome]) -> None:
        self._responses = list(responses)
        self.calls: List[Tuple[str, str, str]] = []

    def send(self, *, recipient: str, recovery_token: str, reconciliation_id: str) -> DeliveryOutcome:
        self.calls.append((recipient, recovery_token, reconciliation_id))
        if len(self._responses) > 1:
            return self._responses.pop(0)
        return self._responses[0]


def delivered(receipt: Optional[str] = "receipt-ok") -> DeliveryOutcome:
    return DeliveryOutcome(delivery_state=models.DeliveryState.DELIVERED, provider_receipt=receipt)


def accepted_delayed(receipt: Optional[str] = "receipt-delayed") -> DeliveryOutcome:
    return DeliveryOutcome(delivery_state=models.DeliveryState.ACCEPTED_DELAYED, provider_receipt=receipt)


def failed(receipt: Optional[str] = "provider unavailable") -> DeliveryOutcome:
    return DeliveryOutcome(delivery_state=models.DeliveryState.FAILED, provider_receipt=receipt)


class _Behavior:
    def __init__(self) -> None:
        self.status = 200
        self.body = b"{}"
        self.captured: List[dict] = []


class FakeMailProviderServer:
    """A tiny real HTTP loopback mail endpoint, controllable per-test."""

    def __init__(self) -> None:
        self.behavior = _Behavior()
        behavior = self.behavior

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, format, *args):
                pass

            def do_POST(self) -> None:  # noqa: N802
                length = int(self.headers.get("Content-Length", "0"))
                raw = self.rfile.read(length)
                try:
                    behavior.captured.append(json.loads(raw.decode("utf-8")))
                except json.JSONDecodeError:
                    behavior.captured.append({})
                body = behavior.body
                self.send_response(behavior.status)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

        self._server = HTTPServer(("127.0.0.1", 0), Handler)
        self._thread = threading.Thread(target=self._server.serve_forever, daemon=True)
        self._thread.start()

    @property
    def url(self) -> str:
        host, port = self._server.server_address
        return f"http://{host}:{port}/mail"

    def set_success(self, *, state: Optional[str] = None, receipt: Optional[str] = None) -> None:
        payload = {}
        if state is not None:
            payload["state"] = state
        if receipt is not None:
            payload["receipt"] = receipt
        self.behavior.status = 200
        self.behavior.body = json.dumps(payload).encode("utf-8")

    def set_failure(self, *, status: int = 503, message: str = "unavailable") -> None:
        self.behavior.status = status
        self.behavior.body = json.dumps({"error": message}).encode("utf-8")

    def last_captured(self) -> Optional[dict]:
        return self.behavior.captured[-1] if self.behavior.captured else None

    def shutdown(self) -> None:
        self._server.shutdown()
        self._server.server_close()
        self._thread.join(timeout=5)

"""Loopback mail delivery client.

Posts a recovery link to the configured mail endpoint and classifies the
response into a delivery state plus an opaque provider receipt. The
receipt's internal shape is never interpreted here or anywhere else in
the service -- it is stored verbatim so a later retry or reconciliation
pass can present it back to whatever provider issued it.
"""
from __future__ import annotations

import json
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Optional

from . import models

MAX_RESPONSE_BYTES = 8192
DEFAULT_TIMEOUT_SECONDS = 5.0


@dataclass(frozen=True)
class DeliveryOutcome:
    delivery_state: str
    provider_receipt: Optional[str]


class Mailer:
    def __init__(self, endpoint: str, *, timeout: float = DEFAULT_TIMEOUT_SECONDS) -> None:
        self._endpoint = endpoint
        self._timeout = timeout

    def send(self, *, recipient: str, recovery_token: str, reconciliation_id: str) -> DeliveryOutcome:
        payload = json.dumps(
            {"recipient": recipient, "recovery_token": recovery_token, "reconciliation_id": reconciliation_id}
        ).encode("utf-8")
        request = urllib.request.Request(
            self._endpoint,
            data=payload,
            method="POST",
            headers={"Content-Type": "application/json"},
        )
        try:
            with urllib.request.urlopen(request, timeout=self._timeout) as response:
                body = response.read(MAX_RESPONSE_BYTES)
                return _classify_success(body)
        except urllib.error.HTTPError as exc:
            with exc:
                body = exc.read(MAX_RESPONSE_BYTES) if exc.fp is not None else b""
            return _classify_failure(body or str(exc).encode("utf-8", "replace"))
        except (urllib.error.URLError, OSError, TimeoutError) as exc:
            return _classify_failure(str(exc).encode("utf-8", "replace"))


def _classify_success(body: bytes) -> DeliveryOutcome:
    text = body.decode("utf-8", "replace")[:MAX_RESPONSE_BYTES]
    state = models.DeliveryState.DELIVERED
    receipt: Optional[str] = text or None
    try:
        parsed = json.loads(text) if text else {}
    except json.JSONDecodeError:
        parsed = {}
    if isinstance(parsed, dict):
        provider_state = parsed.get("state")
        if provider_state == models.DeliveryState.ACCEPTED_DELAYED:
            state = models.DeliveryState.ACCEPTED_DELAYED
        if isinstance(parsed.get("receipt"), str):
            receipt = parsed["receipt"]
    return DeliveryOutcome(delivery_state=state, provider_receipt=receipt)


def _classify_failure(body: bytes) -> DeliveryOutcome:
    text = body.decode("utf-8", "replace")[:MAX_RESPONSE_BYTES]
    return DeliveryOutcome(delivery_state=models.DeliveryState.FAILED, provider_receipt=text or None)

